insert into public.drills (id, dir, topic, sort, context, source) values
('dr-20260926-ke-m1','KR→EN','marketing',1,'구독 서비스 첫 달 무료 배너','첫 달은 무료예요. 언제든 해지할 수 있어요.'),
('dr-20260926-ke-m2','KR→EN','marketing',2,'베이커리 SNS 신메뉴 소개','매일 아침 직접 구운 빵, 오늘은 무화과 캄파뉴가 나왔어요.'),
('dr-20260926-ke-m3','KR→EN','marketing',3,'한정판 화장품 품절 임박 알림','한정 수량으로 준비했어요. 품절되기 전에 서두르세요.'),
('dr-20260926-ke-b1','KR→EN','business',1,'회의 일정 확정 메일','말씀하신 대로 목요일 오후 2시로 회의 일정을 확정하겠습니다.'),
('dr-20260926-ke-b2','KR→EN','business',2,'첨부 파일 누락 사과','앞서 보낸 메일에 파일을 첨부하지 못했습니다. 다시 보내 드립니다.'),
('dr-20260926-ke-b3','KR→EN','business',3,'자료 제출 기한 연장 요청','죄송하지만 자료 제출 기한을 금요일까지 연장해 주실 수 있을까요?'),
('dr-20260926-ke-d1','KR→EN','daily',1,'선물을 받고 친구에게','이런 걸 뭘 사 왔어. 마음만으로도 충분한데.'),
('dr-20260926-ke-d2','KR→EN','daily',2,'늦은 밤 친구와 문자를 마무리하며','벌써 시간이 이렇게 됐네. 내일 출근해야 하니까 먼저 잘게.'),
('dr-20260926-ke-d3','KR→EN','daily',3,'분위기 좋은 식당에서 친구에게','여기 분위기 완전 내 스타일이야. 다음에 또 오자.'),
('dr-20260926-ke-t1','KR→EN','travel',1,'호텔 방을 바꿔 달라고 할 때','방에서 담배 냄새가 나는데, 다른 방으로 바꿀 수 있을까요?'),
('dr-20260926-ke-t2','KR→EN','travel',2,'현지인에게 식당 추천 부탁','관광객 말고 현지 사람들이 자주 가는 식당이 있으면 추천해 주세요.'),
('dr-20260926-ke-t3','KR→EN','travel',3,'택시 기사에게','공항까지 얼마나 걸릴까요? 5시 비행기라서요.'),
('dr-20260926-ek-m1','EN→KR','marketing',1,'러닝화 광고 카피','Built for the long run.'),
('dr-20260926-ek-m2','EN→KR','marketing',2,'숙소 예약 사이트 배너','Your perfect getaway is just a click away.'),
('dr-20260926-ek-m3','EN→KR','marketing',3,'앱 업데이트 안내','We''ve squashed some bugs and made things run smoother.'),
('dr-20260926-ek-b1','EN→KR','business',1,'미팅 후 감사 메일','Thanks for taking the time to meet with us today.'),
('dr-20260926-ek-b2','EN→KR','business',2,'회신 기한 안내','We''d appreciate it if you could get back to us by the end of the week.'),
('dr-20260926-ek-b3','EN→KR','business',3,'초안 검토 요청','I''d love to hear your thoughts on the draft.'),
('dr-20260926-ek-d1','EN→KR','daily',1,'친구의 제안에 답하기','I''m down. What time works for you?'),
('dr-20260926-ek-d2','EN→KR','daily',2,'친구가 미안해할 때','No worries, it''s not a big deal at all.'),
('dr-20260926-ek-d3','EN→KR','daily',3,'오랜만에 친구에게 연락하며','Sorry I''ve been MIA lately. Life got crazy.'),
('dr-20260926-ek-t1','EN→KR','travel',1,'기차역 안내 방송','The train now arriving at platform 3 is the express service to Busan.'),
('dr-20260926-ek-t2','EN→KR','travel',2,'숙소 체크아웃 안내','Late checkout is available upon request, subject to availability.'),
('dr-20260926-ek-t3','EN→KR','travel',3,'공항 보안 검색대 안내','Please remove all liquids and laptops from your bag.')
insert into public.drill_models (drill_id, best, alternatives, notes) values
('dr-20260926-ke-m1','Your first month is on us. Cancel anytime.','["Try your first month free. Cancel anytime.", "First month free, and you can cancel whenever you like."]','[{"phrase": "첫 달은 무료예요 → Your first month is on us", "why": "free도 맞지만 on us(저희가 낼게요)가 광고에서 더 친근하게 들려요."}, {"phrase": "언제든 해지할 수 있어요 → Cancel anytime", "why": "You can cancel at any time처럼 길게 쓰기보다 두 단어 명령문이 배너에 맞아요."}]'),
('dr-20260926-ke-m2','Baked fresh every morning. Today''s special: fig campagne.','["Fresh from our oven every morning, and today it''s fig campagne.", "Our bread is baked in-house every morning, and today we''ve got fig campagne."]','[{"phrase": "직접 구운 → baked fresh / baked in-house", "why": "직접을 directly로 옮기면 틀려요. 가게에서 구웠다는 뜻은 in-house, fresh from our oven이에요."}, {"phrase": "오늘은 ~이 나왔어요 → Today''s special", "why": "나왔다를 came out으로 직역하면 어색해요. 오늘 메뉴를 알릴 때는 today''s special이나 we''ve got을 써요."}]'),
('dr-20260926-ke-m3','Available in limited quantities. Get yours before it''s gone.','["Limited stock. Grab yours before it sells out.", "Only a few left, so don''t miss out."]','[{"phrase": "한정 수량 → limited quantities / limited stock", "why": "limited number of products보다 굳어진 광고 표현을 써요."}, {"phrase": "품절되기 전에 → before it''s gone / before it sells out", "why": "before sold out은 문법이 틀려요. sell out은 동사, sold out은 형용사예요."}]'),
('dr-20260926-ke-b1','I''d like to confirm our meeting for Thursday at 2 p.m., as you suggested.','["As suggested, let''s confirm the meeting for Thursday at 2 p.m.", "Thursday at 2 p.m. works well for us. I''ll send over a calendar invite."]','[{"phrase": "말씀하신 대로 → as you suggested", "why": "as you said도 틀리진 않지만, 상대 제안을 받아들이는 업무 메일에서는 as you suggested가 자연스러워요."}, {"phrase": "확정하겠습니다 → I''d like to confirm", "why": "decide가 아니라 confirm이에요. I''d like to로 공손함을 살려요."}]'),
('dr-20260926-ke-b2','Apologies, I forgot to attach the file to my previous email. Please find it attached here.','["Sorry, the attachment was missing from my last email. Here it is.", "I realized I left out the attachment earlier, so I''m resending it now."]','[{"phrase": "첨부하지 못했습니다 → I forgot to attach", "why": "could not attach는 기술적으로 못 했다는 뜻으로 들려요. 실수로 빠뜨린 건 forgot to attach, left out이에요."}, {"phrase": "다시 보내 드립니다 → Please find it attached", "why": "업무 메일에서 첨부를 알리는 굳어진 표현이에요. 조금 편하게는 Here it is."}]'),
('dr-20260926-ke-b3','Would it be possible to extend the deadline for the materials to Friday?','["I''m sorry to ask, but could we push the deadline back to Friday?", "Could I have until Friday to submit the materials?"]','[{"phrase": "죄송하지만 → (생략) / I''m sorry to ask, but", "why": "한국어 부탁 앞의 죄송하지만은 영어에서 자주 빼고, Would it be possible로 공손함을 대신해요."}, {"phrase": "기한을 연장하다 → extend the deadline", "why": "lengthen the deadline이 아니라 extend가 짝을 이루는 말이에요. 편하게는 push the deadline back."}]'),
('dr-20260926-ke-d1','You shouldn''t have! It''s the thought that counts.','["Aw, you didn''t have to get me anything.", "You really didn''t need to, but thank you!"]','[{"phrase": "이런 걸 뭘 사 왔어 → You shouldn''t have!", "why": "왜 샀냐고 따지는 말이 아니라 고마움을 나타내는 관용 표현이에요. Why did you buy this?는 정말 따지는 말로 들려요."}, {"phrase": "마음만으로도 충분한데 → It''s the thought that counts", "why": "마음을 heart로 직역하지 않아요. 선물에 담긴 마음을 말할 때 쓰는 굳어진 표현이에요."}]'),
('dr-20260926-ke-d2','Wow, look at the time. I''ve got work tomorrow, so I''m going to call it a night.','["It''s gotten late and I have work in the morning, so I''m heading to bed.", "Didn''t realize how late it was. Gotta work tomorrow, so good night!"]','[{"phrase": "벌써 시간이 이렇게 됐네 → Look at the time", "why": "시간이 벌써 늦었다는 뜻의 관용 표현이에요."}, {"phrase": "먼저 잘게 → call it a night / head to bed", "why": "먼저(first)는 옮기지 않아요. 대화를 끝내고 자러 갈 때 call it a night을 써요."}]'),
('dr-20260926-ke-d3','This place is totally my vibe. Let''s come back sometime.','["I love the atmosphere here. We should come again.", "This spot is right up my alley. Let''s definitely come back."]','[{"phrase": "내 스타일이야 → my vibe / right up my alley", "why": "This is my style도 통하지만, 구어에서는 my vibe나 right up my alley가 더 자연스러워요."}, {"phrase": "다음에 또 오자 → Let''s come back sometime", "why": "next time을 꼭 넣지 않아도 돼요. come back, come again이 다시 온다는 뜻이에요."}]'),
('dr-20260926-ke-t1','My room smells like smoke. Would it be possible to switch to a different room?','["There''s a cigarette smell in my room. Could I be moved to another one?", "Is there any chance I could change rooms? Mine smells of smoke."]','[{"phrase": "담배 냄새가 나다 → smells like smoke", "why": "tobacco smell보다 smell like smoke, cigarette smell이 자연스러워요."}, {"phrase": "방을 바꾸다 → switch / change rooms", "why": "change rooms는 rooms를 복수로 써요. change my room은 방을 꾸민다는 뜻으로 들릴 수 있어요."}]'),
('dr-20260926-ke-t2','Could you recommend a restaurant where the locals actually eat, not a tourist spot?','["Where do locals like to eat around here? Somewhere off the tourist track would be great.", "Any restaurants the locals love? I''d rather avoid the touristy places."]','[{"phrase": "관광객 말고 → not a tourist spot / touristy", "why": "touristy는 관광객용이라 비싸고 평범하다는 느낌이 담긴 형용사예요."}, {"phrase": "현지 사람들 → the locals", "why": "local people도 되지만 locals 한 단어가 자연스러워요."}]'),
('dr-20260926-ke-t3','How long will it take to get to the airport? My flight is at five.','["About how long to the airport? I''ve got a five o''clock flight.", "Will we make it to the airport in time? My flight leaves at five."]','[{"phrase": "얼마나 걸릴까요 → How long will it take", "why": "시간이 걸리다는 take예요. spend는 사람이 시간을 쓰는 거예요."}, {"phrase": "5시 비행기라서요 → My flight is at five", "why": "because를 넣어 이유를 직역하지 않아도 돼요. 사실만 말하면 이유가 전해져요."}]'),
('dr-20260926-ek-m1','오래 달리도록, 오래 가도록.','["긴 거리도, 긴 시간도 끄떡없이.", "멀리 달리는 사람을 위해 만들었어요."]','[{"phrase": "the long run", "why": "장거리 달리기와 in the long run(오래도록)을 겹친 말장난이에요. 두 뜻을 다 살리려면 대구로 옮겨요."}, {"phrase": "Built for", "why": "~를 위해 만들어진은 번역투가 되기 쉬워요. 카피에서는 목적만 남기고 짧게 써요."}]'),
('dr-20260926-ek-m2','완벽한 휴가, 클릭 한 번이면 떠날 수 있어요.','["클릭 한 번으로 떠나는 나만의 휴가", "꿈꾸던 휴가, 클릭 한 번이면 충분해요."]','[{"phrase": "getaway", "why": "도망이 아니라 짧은 휴가, 여행이에요."}, {"phrase": "just a click away", "why": "클릭 한 번 떨어져 있다는 직역 대신 클릭 한 번이면 된다로 풀어요. getaway와 away의 운율은 떠나다로 살릴 수 있어요."}]'),
('dr-20260926-ek-m3','몇 가지 오류를 고치고 더 매끄럽게 움직이도록 개선했어요.','["버그를 잡고 속도를 개선했어요.", "자잘한 오류를 고치고 사용감을 더 부드럽게 다듬었어요."]','[{"phrase": "squashed some bugs", "why": "벌레를 눌러 잡는다는 비유예요. 한국어 앱 안내에서는 버그를 잡았다, 오류를 고쳤다로 써요."}, {"phrase": "made things run smoother", "why": "things는 옮기지 않아요. 앱이 더 매끄럽게 움직인다로 주어를 앱으로 봐요."}]'),
('dr-20260926-ek-b1','오늘 바쁘신 중에 시간 내 주셔서 감사합니다.','["오늘 귀한 시간 내어 만나 주셔서 감사합니다.", "오늘 미팅에 시간 내 주셔서 고맙습니다."]','[{"phrase": "taking the time", "why": "시간을 가져 주셔서가 아니라 시간을 내 주셔서예요."}, {"phrase": "(바쁘신 중에)", "why": "원문에 없지만 한국어 업무 메일의 감사 인사에 자주 붙는 말이에요. 넣어도 뜻이 달라지지 않아요."}]'),
('dr-20260926-ek-b2','이번 주 안으로 회신 주시면 감사하겠습니다.','["금주 중으로 답변 부탁드립니다.", "이번 주 금요일까지 회신해 주시면 감사하겠습니다."]','[{"phrase": "get back to us", "why": "우리에게 돌아오다가 아니라 답을 주다, 회신하다예요."}, {"phrase": "by the end of the week", "why": "주말까지로 옮기면 토·일요일로 오해할 수 있어요. 업무에서는 보통 금요일까지라 이번 주 안으로가 정확해요."}]'),
('dr-20260926-ek-b3','초안에 대한 의견을 듣고 싶습니다.','["초안 보시고 의견 주시면 감사하겠습니다.", "초안을 어떻게 보셨는지 궁금합니다."]','[{"phrase": "I''d love to", "why": "사랑하다가 아니라 꼭 ~하고 싶다는 공손한 표현이에요."}, {"phrase": "your thoughts", "why": "당신의 생각들로 직역하지 않아요. 업무에서는 의견이에요."}]'),
('dr-20260926-ek-d1','콜! 몇 시가 좋아?','["좋아, 나도 갈래. 몇 시 괜찮아?", "나 완전 가능. 언제가 편해?"]','[{"phrase": "I''m down", "why": "기분이 처졌다는 뜻이 아니에요. 제안에 찬성할 때 쓰는 구어라 콜, 좋아예요. I''m feeling down은 우울하다예요."}, {"phrase": "What time works for you?", "why": "무슨 시간이 너에게 작동하냐가 아니라 몇 시가 괜찮냐예요."}]'),
('dr-20260926-ek-d2','걱정 마, 별일 아니야.','["괜찮아, 전혀 신경 안 써도 돼.", "에이, 아무것도 아니야."]','[{"phrase": "No worries", "why": "걱정이 없다가 아니라 괜찮아, 신경 쓰지 마예요."}, {"phrase": "not a big deal", "why": "큰 거래가 아니라 별일 아니다, 대수롭지 않다예요."}]'),
('dr-20260926-ek-d3','요즘 연락 못 해서 미안. 정신없이 지냈어.','["한동안 잠수 타서 미안해. 요즘 너무 바빴어.", "연락 뜸했지? 미안, 이것저것 일이 많았어."]','[{"phrase": "MIA", "why": "missing in action(전투 중 실종)에서 온 구어예요. 연락이 끊겼다, 잠수 탔다는 뜻이에요."}, {"phrase": "Life got crazy", "why": "인생이 미쳤다가 아니라 정신없이 바빴다예요."}]'),
('dr-20260926-ek-t1','지금 3번 승강장에 들어오는 열차는 부산행 급행열차입니다.','["3번 타는 곳에 도착하는 열차는 부산행 급행열차입니다.", "이번에 3번 승강장으로 들어오는 열차는 부산으로 가는 급행입니다."]','[{"phrase": "now arriving at platform 3", "why": "안내 방송은 들어오는 열차는으로 주어를 앞에 두고 짧게 써요."}, {"phrase": "express service to Busan", "why": "부산으로의 급행 서비스가 아니라 부산행 급행열차예요. service는 옮기지 않아요."}]'),
('dr-20260926-ek-t2','요청하시면 레이트 체크아웃이 가능하며, 객실 상황에 따라 어려울 수 있습니다.','["레이트 체크아웃은 요청 시 가능하나, 객실 사정에 따라 제한될 수 있습니다.", "늦은 체크아웃을 원하시면 말씀해 주세요. 객실 상황에 따라 가능 여부가 달라집니다."]','[{"phrase": "upon request", "why": "요청에 따라, 요청하시면이에요."}, {"phrase": "subject to availability", "why": "가용성에 따른다는 직역은 어색해요. 호텔 안내에서는 객실 상황에 따라예요."}]'),
('dr-20260926-ek-t3','가방에서 액체류와 노트북을 모두 꺼내 주세요.','["액체류와 노트북은 가방에서 꺼내 따로 올려 주세요.", "가방 속 액체류와 노트북을 모두 꺼내 주시기 바랍니다."]','[{"phrase": "remove", "why": "제거하다가 아니라 꺼내다예요. 상황에 맞는 동사를 골라요."}, {"phrase": "liquids", "why": "액체들이 아니라 공항에서 쓰는 말인 액체류예요."}]')
